#!/usr/bin/env bash
# Release build of the pinned-tree parano1d node for x86-64 Linux (forge-bench).
# Mirrors the devnet-chaos bin/parano1d recipe: v1 pack (locally generated by
# the project's own script, carried over from that lane), v2 pack + retirement
# keys and v21 pack downloaded from the public v2.1.0 GitHub release and
# SHA256SUMS-verified there; banks/pins from each pack's pins.env.
# Run on hbox under: swarm-build SWARM_MEM_MAX=16G bash build_node_hbox.sh
set -euo pipefail

LANE=/home/hbox/lanes/forge-bench
cd "$LANE/parano1d-src"

export NOID_HISTORY_STEP_PACK_DIR="$LANE/packs/history-step-v1"
export NOID_HISTORY_STEP_RUNTIME_METADATA_RELEASE_DIGEST=ad463bd76e27df3c0f414f4fd7640cfb5c45cc7f3a09e44a2f7bc7a8b869485b
export NOID_V2_PACK_DIR="$LANE/downloads-v2/history-step-pack-v2"
export NOID_V2_RELEASE_BANK=c2a6df736b0d0da22e285b6930b11cf44b520d65b52c7dfe78f44fe0cd48e76e
export NOID_RETIREMENT_KEYS_DIR="$LANE/downloads-v2/history-step-pack-v2/retirement-keys"
export NOID_RETIREMENT_KEY_0_PIN=0651ce507810b61213cbdc0e9f99436aec3a7922cc662bfba6128b466453c8b2
export NOID_RETIREMENT_KEY_1_PIN=c301274d50dc02fd5c383f2e71629075729a954a768f5051388ec2040bce0267
export NOID_V21_PACK_DIR="$LANE/downloads-v21/history-step-pack-v21"
export NOID_V21_RELEASE_BANK=6c280ae869afc25e31d46d73b42870512991b78c9498bc7e5ef939bc07e5ed5e

export CARGO_TARGET_DIR="$LANE/target-node-rel"
cargo build --release -p noid_node --bin parano1d
echo NODE_BUILD_DONE
